"""Standalone HTML for the same-origin WebView2 floating task ball."""

FLOATBALL_PAGE_HTML = r'''<!doctype html>
<html lang="zh-CN" data-theme="light">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>群务台 · 浮球</title>
<style>
:root{color-scheme:light;--page:#e8ebee;--paper:#fff;--paper-alt:#f2f4f6;--ink:#172722;--muted:#3d4f47;--line:#b0b8bd;--teal:#12695b;--teal-soft:#d6ede7;--amber:#805411;--amber-soft:#fff3db;--red:#a5312d;--red-soft:#ffeeed;--ease-in:cubic-bezier(.2,.8,.2,1);--ease-out:cubic-bezier(.4,0,1,1)}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){color-scheme:dark;--page:#0a0c12;--paper:#141925;--paper-alt:#1a2234;--ink:#f3f5fa;--muted:#b7c0d0;--line:#6a7284;--teal:#2ba895;--teal-soft:#193f39;--amber:#ffb84d;--amber-soft:#433416;--red:#ff6b6f;--red-soft:#522120}}
body{position:fixed;inset:0}*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:transparent;color:var(--ink);font:14px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif}button{font:inherit;color:inherit}.stage{position:fixed;right:0;bottom:0;z-index:1;width:72px;height:72px;padding:0}.ball{position:relative;z-index:2;display:grid;place-items:center;width:72px;height:72px;flex:none;padding:0;border:1px solid var(--line);border-radius:50%;background:var(--teal);color:#fff;box-shadow:0 4px 12px rgba(0,0,0,.2);cursor:pointer;touch-action:none;user-select:none;transition:transform 120ms var(--ease-in),box-shadow 120ms ease-out}.ball:hover{transform:translateY(-2px);box-shadow:0 7px 16px rgba(0,0,0,.24)}.ball:active{transform:scale(.98)}.ball svg{width:25px;height:25px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.badge{position:absolute;top:2px;right:2px;display:grid;place-items:center;min-width:20px;height:20px;padding:0 4px;border:2px solid var(--paper);border-radius:999px;background:var(--red);color:#fff;font-size:12px;line-height:16px;font-weight:750;font-variant-numeric:tabular-nums}.badge.bump{animation:badge-bump 160ms var(--ease-in)}@keyframes badge-bump{from{transform:scale(.88)}to{transform:scale(1)}}.panel{position:fixed;inset:0;width:100%;height:100%;max-height:100%;overflow:auto;padding:12px;border:1px solid var(--line);border-radius:12px;background:var(--paper);color:var(--ink);box-shadow:0 12px 32px rgba(0,0,0,.24);opacity:0;transform:translateY(6px) scale(.98);transform-origin:bottom right;visibility:hidden;pointer-events:none;transition:opacity 200ms var(--ease-in),transform 200ms var(--ease-in),visibility 0s linear 200ms}.panel.open{opacity:1;transform:none;visibility:visible;pointer-events:auto;transition:opacity 200ms var(--ease-in),transform 200ms var(--ease-in)}.panel.closing{opacity:0;transform:translateY(4px) scale(.98);visibility:visible;pointer-events:none;transition:opacity 140ms var(--ease-out),transform 140ms var(--ease-out),visibility 0s linear 140ms}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:0 2px 10px}.panel-head h1{margin:0;font-size:16px;line-height:24px}.count{color:var(--muted);font-size:12px;font-weight:500}.head-actions{display:flex;align-items:center;gap:6px}.head-btn{display:grid;place-items:center;min-width:36px;height:36px;padding:0 8px;border:1px solid var(--line);border-radius:7px;background:var(--paper);cursor:pointer}.head-btn:hover,.action:hover{border-color:var(--teal);background:var(--teal-soft)}.head-btn:disabled,.action:disabled{opacity:.55;cursor:wait}.group{margin-top:10px}.group-label{display:flex;align-items:center;gap:6px;margin:0 2px 6px;color:var(--muted);font-size:11px;font-weight:750;letter-spacing:.04em}.group-label:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--teal)}.group.urgent .group-label:before{background:var(--amber)}.entry{margin-top:6px;padding:9px;border:1px solid var(--line);border-radius:8px;background:var(--paper);transition:opacity 180ms var(--ease-out),transform 180ms var(--ease-out)}.entry[data-urgent="true"]{border-left:3px solid var(--amber)}.entry[aria-busy="true"]{opacity:.72}.entry.done-flash{transform:translateY(-4px);opacity:0}.entry-head{display:flex;align-items:flex-start;justify-content:space-between;gap:8px}.summary{min-width:0;padding:0;border:0;background:transparent;color:var(--ink);text-align:left;font-size:14px;line-height:1.4;font-weight:700;cursor:pointer;overflow-wrap:anywhere}.tag{flex:none;padding:2px 6px;border:1px solid var(--line);border-radius:999px;background:var(--paper-alt);color:var(--muted);font-size:10px;line-height:16px}.tag.urgent{border-color:var(--amber);background:var(--amber-soft);color:var(--amber)}.tag.new{border-color:var(--teal);background:var(--teal-soft);color:var(--teal)}.row-meta{display:flex;flex-wrap:wrap;gap:5px 10px;margin-top:6px;color:var(--muted);font-size:11px}.preview{display:-webkit-box;margin:5px 0 0;color:var(--muted);font-size:12px;line-height:1.4;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2}.detail{display:none;margin-top:8px;padding:8px;border-radius:6px;background:var(--paper-alt);color:var(--ink);font-size:12px;overflow-wrap:anywhere}.entry.expanded .detail{display:block}.detail p{margin:0 0 6px;white-space:pre-wrap}.detail p:last-child{margin-bottom:0}.detail-label{color:var(--muted);font-weight:650}.actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.action{min-height:34px;padding:5px 9px;border:1px solid var(--line);border-radius:6px;background:var(--paper-alt);color:var(--ink);font-size:11px;font-weight:650;cursor:pointer}.action.primary{border-color:var(--teal);background:var(--teal);color:#fff}.action.primary:hover{background:var(--teal-soft);color:var(--ink)}.action.pin[aria-pressed="true"]{border-color:var(--teal);background:var(--teal-soft);color:var(--teal)}.state{min-height:18px;margin:8px 2px 0;color:var(--muted);font-size:11px}.state[data-kind="error"]{color:var(--red)}.state[data-kind="success"]{color:var(--teal)}.empty{margin:8px 2px;color:var(--muted);font-size:12px}.retry{margin:6px 2px 0;min-height:36px;padding:6px 10px;border:1px solid var(--line);border-radius:6px;background:var(--paper-alt);cursor:pointer}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}button:focus-visible{outline:2px solid var(--teal);outline-offset:2px}.new-marker{display:inline-block;margin-left:5px;padding:0 5px;border-radius:999px;background:var(--teal-soft);color:var(--teal);font-size:10px;font-weight:700}.hide{display:none!important}html{scrollbar-width:none;overflow:hidden}::-webkit-scrollbar{width:0;height:0;display:none}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}.entry.done-flash{transform:none}}
</style>
</head>
<body>
<div class="stage" id="stage">
<section class="panel" id="panel" aria-label="待处理列表" aria-hidden="true" inert>
<header class="panel-head"><div><h1>待处理 <span class="count" id="badgeCount">· 读取中</span></h1></div><div class="head-actions"><button class="head-btn" id="refresh" type="button" aria-label="刷新待办列表" title="刷新">↻</button><button class="head-btn" id="close" type="button" aria-label="收起列表" title="收起">×</button></div></header>
<div id="list"><p class="empty" id="loading">正在读取任务…</p></div>
<p class="state" id="state" role="status" aria-live="polite">浮球已连接</p>
</section>
<button class="ball" id="ball" type="button" aria-label="打开待处理列表" aria-expanded="false" aria-controls="panel" title="待处理">
<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span class="badge" id="badge" aria-label="0 条待处理">0</span>
</button>
</div>
<script>
(function(){
'use strict';
var token=new URLSearchParams(location.search).get('token')||'';
var LAST_OPEN_KEY='nh_floatball_last_open';
var state={open:false,tasksPayload:null,inbox:[],taskError:'',inboxError:'',lastOpenedAt:0,sessionReadAt:0,visibleTasks:[],busy:Object.create(null)};
var ball=document.getElementById('ball'),panel=document.getElementById('panel'),stage=document.getElementById('stage'),badge=document.getElementById('badge'),badgeCount=document.getElementById('badgeCount'),list=document.getElementById('list'),status=document.getElementById('state');
function esc(value){return String(value==null?'':value).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function text(value){if(value==null)return '';if(Array.isArray(value))return value.map(function(v){return String(v==null?'':v).trim();}).filter(Boolean).join('、');return String(value).trim();}
function requestJson(path,options){options=options||{};var init=Object.assign({cache:'no-store'},options);init.headers=Object.assign({'X-Token':token,'Accept':'application/json'},options.headers||{});return fetch(path,init).then(function(response){return response.text().then(function(raw){var payload;try{payload=raw?JSON.parse(raw):{};}catch(_error){throw new Error('服务返回了无法读取的数据（HTTP '+response.status+'）');}if(!response.ok||payload.ok===false)throw new Error(text(payload.error||payload.reason)||('请求失败（HTTP '+response.status+'）'));return payload;});});}
function taskKey(task){return task&&task.id!=null?String(task.id):'';}
function activeTasks(data){var all=[].concat(data.today||[],data.week||[],data.later||[],data.candidates||[],data.pinned||[]),seen=Object.create(null),out=[];all.forEach(function(task){var id=taskKey(task);if(!id||seen[id]||task.done===true||String(task.status||'')==='done'||String(task.status||'')==='dismissed'||String(task.status||'')==='expired')return;seen[id]=true;out.push(task);});out.sort(function(a,b){var urgentA=!!a.effective_urgent,urgentB=!!b.effective_urgent;if(urgentA!==urgentB)return urgentA?-1:1;var timeA=Date.parse(String(a.deadline||'')),timeB=Date.parse(String(b.deadline||'')),validA=Number.isFinite(timeA),validB=Number.isFinite(timeB);if(validA!==validB)return validA?-1:1;if(validA&&timeA!==timeB)return timeA-timeB;return 0;});return out;}
function inboxFor(task){var id=taskKey(task),key=text(task.task_key);for(var i=0;i<state.inbox.length;i++){var item=state.inbox[i];if((item.task_id!=null&&String(item.task_id)===id)||(key&&String(item.msg_id||'')===key))return item;}return null;}
function badgeTotal(data){return (data.candidates||[]).length+(data.today||[]).length+(data.week||[]).length;}
function isNew(task,item){if(!state.lastOpenedAt)return false;var created=Date.parse(String(task.created_at||''));if(!Number.isFinite(created)&&item)created=Date.parse(String(item.received_at||''));return Number.isFinite(created)&&created>state.lastOpenedAt;}
function detailField(label,value){value=text(value);return value?'<p><span class="detail-label">'+esc(label)+'：</span>'+esc(value)+'</p>':'';}
function renderItem(task,index){var item=inboxFor(task),candidate=String(task.status||'')==='candidate',urgent=!!task.effective_urgent,newItem=isNew(task,item),groups=text(task.groups)||(item?text(item.group_name):''),summary=text(task.summary)||'未命名事项',deadline=text(task.deadline_text),source=text(task.source_text),content=item?text(item.content):'';var tags=(candidate?'<span class="tag">待确认</span>':'')+(urgent?'<span class="tag urgent">紧急</span>':'')+(task.pinned?'<span class="tag">置顶</span>':'')+(newItem?'<span class="tag new">新</span>':'');var meta=(deadline?'<span>'+esc(deadline)+'</span>':'')+(groups?'<span>'+esc(groups)+'</span>':'');var details=detailField('事项',summary)+detailField('截止时间',deadline)+detailField('群组',groups)+detailField('原文',source)+detailField('补充详情',task.details)+ (item?(detailField('群名',item.group_name)+detailField('发送人',item.sender_name)+detailField('消息内容',content)):'');if(!details)details='<p>暂无更多详情</p>';var actions=candidate?'<button class="action primary" type="button" data-action="confirm" data-index="'+index+'">确认待办</button><button class="action" type="button" data-action="snooze" data-index="'+index+'">稍后</button><button class="action" type="button" data-action="dismiss" data-index="'+index+'">忽略</button>':'<button class="action primary" type="button" data-action="done" data-index="'+index+'">完成</button><button class="action" type="button" data-action="snooze" data-index="'+index+'">稍后</button><button class="action" type="button" data-action="dismiss" data-index="'+index+'">忽略</button>';var pinned=!!task.pinned;actions+='<button class="action pin" type="button" data-action="pin" data-index="'+index+'" aria-pressed="'+pinned+'">'+(pinned?'取消置顶':'置顶')+'</button>';var preview=source||content||text(task.details);return '<article class="entry" data-id="'+esc(taskKey(task))+'" data-urgent="'+urgent+'"><div class="entry-head"><button class="summary" type="button" data-action="expand" data-index="'+index+'" aria-expanded="false">'+esc(summary)+'</button><span>'+tags+'</span></div>'+(meta?'<div class="row-meta">'+meta+'</div>':'')+(preview?'<p class="preview">'+esc(preview)+'</p>':'')+'<div class="detail">'+details+'</div><div class="actions">'+actions+'</div></article>';}
function render(){var data=state.tasksPayload;if(!data){list.innerHTML='<p class="empty">'+esc(state.taskError||'正在读取任务…')+'</p><button class="retry" id="retry" type="button">重试</button>';document.getElementById('retry').onclick=refresh;badge.textContent='!';badge.setAttribute('aria-label','任务读取失败');badgeCount.textContent='· 加载失败';return;}var total=badgeTotal(data);badge.textContent=total>99?'99+':String(total);badge.setAttribute('aria-label',total+' 条待处理');badgeCount.textContent='· '+total+' 条';state.visibleTasks=activeTasks(data);if(!state.visibleTasks.length){list.innerHTML='<p class="empty">没有需要处理的任务</p>';return;}var urgent=[],regular=[];state.visibleTasks.forEach(function(task,index){(task.effective_urgent?urgent:regular).push(renderItem(task,index));});var html='';if(urgent.length)html+='<section class="group urgent"><h2 class="group-label">紧急</h2>'+urgent.join('')+'</section>';if(regular.length)html+='<section class="group"><h2 class="group-label">待处理</h2>'+regular.join('')+'</section>';list.innerHTML=html;}
function showState(message,kind){status.textContent=message||'';status.dataset.kind=kind||'';}
function setOpen(open){if(state.open===open)return;state.open=open;document.title='nh-floatball:'+(open?'open':'closed')+':'+window.innerWidth+'x'+window.innerHeight;panel.classList.remove('closing');panel.classList.toggle('open',open);panel.setAttribute('aria-hidden',String(!open));if('inert'in panel)panel.inert=!open;ball.setAttribute('aria-expanded',String(open));if(open){var previous=0;try{previous=Date.parse(localStorage.getItem(LAST_OPEN_KEY)||'')||0;localStorage.setItem(LAST_OPEN_KEY,new Date().toISOString());}catch(_error){}state.lastOpenedAt=previous;render();document.getElementById('close').focus();}else ball.focus();}
function readTaskData(){if(!token){state.taskError='缺少访问令牌，请从带 token 的浮球地址打开。';state.tasksPayload=null;render();return Promise.resolve();}state.taskError='';var taskPromise=requestJson('/api/tasks').then(function(data){state.tasksPayload=data;state.taskError='';}).catch(function(error){state.taskError=error.message;});var inboxPromise=requestJson('/api/inbox?limit=100').then(function(data){state.inbox=Array.isArray(data.items)?data.items:[];state.inboxError='';}).catch(function(error){state.inbox=[];state.inboxError=error.message;});return Promise.all([taskPromise,inboxPromise]).then(function(){render();if(state.inboxError)showState('任务已加载；收件箱详情暂不可用：'+state.inboxError,'error');else if(state.taskError)showState('任务读取失败：'+state.taskError,'error');else showState('已更新','success');});}
function refresh(){var button=document.getElementById('refresh');button.disabled=true;showState('正在刷新…','');return readTaskData().then(function(){button.disabled=false;},function(error){button.disabled=false;showState('刷新失败：'+error.message,'error');});}
function mutate(task,action,button){var id=taskKey(task);if(!/^\d+$/.test(id)){showState('任务 ID 无效，无法提交操作。','error');return;}var card=button.closest('.entry'),buttons=card?card.querySelectorAll('button'):[];Array.prototype.forEach.call(buttons,function(control){control.disabled=true;});if(card)card.setAttribute('aria-busy','true');showState('正在提交操作…','');requestJson('/api/tasks/'+encodeURIComponent(id),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:action})}).then(function(result){if(result.ok!==true)throw new Error(text(result.error)||'服务端未确认操作');if(action==='done')return new Promise(function(resolve){if(card)card.classList.add('done-flash');window.setTimeout(resolve,180);});}).then(function(){return readTaskData();}).then(function(){if(state.taskError)showState('服务端已确认，但列表刷新失败：'+state.taskError,'error');else showState(action==='done'?'已完成。':action==='snooze'?'已稍后提醒。':action==='dismiss'?'已忽略。':'已确认待办。','success');}).catch(function(error){showState('操作失败，任务仍保留：'+error.message,'error');}).then(function(){Array.prototype.forEach.call(buttons,function(control){control.disabled=false;});if(card)card.removeAttribute('aria-busy');});}
function togglePin(task,button){var id=taskKey(task);if(!/^\d+$/.test(id)){showState('任务 ID 无效，无法置顶。','error');return;}button.disabled=true;var value=!task.pinned;showState(value?'正在置顶…':'正在取消置顶…','');requestJson('/api/tasks/pin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:id,pinned:value})}).then(function(result){if(result.ok!==true)throw new Error(text(result.error)||'服务端未确认置顶操作');return readTaskData();}).then(function(){if(state.taskError)showState('置顶已由服务端确认，但列表刷新失败：'+state.taskError,'error');else showState(value?'已置顶。':'已取消置顶。','success');}).catch(function(error){showState('置顶操作失败，原状态已保留：'+error.message,'error');}).then(function(){button.disabled=false;});}
ball.addEventListener('click',function(){setOpen(!state.open);});document.getElementById('close').addEventListener('click',function(){setOpen(false);});document.getElementById('refresh').addEventListener('click',refresh);document.addEventListener('pointerdown',function(event){if(state.open&&!panel.contains(event.target)&&!ball.contains(event.target))setOpen(false);});document.addEventListener('keydown',function(event){if(event.key==='Escape'&&state.open)setOpen(false);});list.addEventListener('click',function(event){var button=event.target.closest('[data-action]');if(!button)return;var index=Number(button.dataset.index),task=state.visibleTasks[index];if(!task)return;var action=button.dataset.action;if(action==='expand'){var card=button.closest('.entry'),expanded=card.classList.toggle('expanded');button.setAttribute('aria-expanded',String(expanded));return;}if(action==='pin'){togglePin(task,button);return;}mutate(task,action,button);});
function placeInitial(){}
placeInitial();function syncTitle(){document.title='nh-floatball:'+(state.open?'open':'closed')+':'+window.innerWidth+'x'+window.innerHeight;}syncTitle();window.addEventListener('resize',syncTitle);readTaskData();window.setInterval(function(){if(document.visibilityState==='visible')readTaskData();},60000);document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')readTaskData();});
})();
</script>
</body>
</html>'''


def render() -> str:
    """Return the standalone floating-ball page; its API calls are same-origin."""
    return FLOATBALL_PAGE_HTML


__all__ = ["FLOATBALL_PAGE_HTML", "render"]
